const historyLabel=action=>({created:'Pedido recebido',approve:'Mensagem aprovada',reject:'Mensagem reprovada',pay:'Pagamento confirmado',refund:'Devolução registrada',publish:'Mensagem veiculada','payment-claimed':'Pagamento informado por você',reminder_sent:'Lembrete da ofensiva enviado',reminder_optout:'Lembretes cancelados'}[action]||'Pedido atualizado');
