let renderVersion=0;
function registerActiveDay(){const parts=new Intl.DateTimeFormat('en-CA',{timeZone:'America/Sao_Paulo',year:'numeric',month:'2-digit',day:'2-digit'}).formatToParts(new Date()),map=Object.fromEntries(parts.map(x=>[x.type,x.value])),today=map.year+'-'+map.month+'-'+map.day,prev=new Date(Date.UTC(Number(map.year),Number(map.month)-1,Number(map.day))-86400000).toISOString().slice(0,10),p=state.profile||{};if(p.lastActiveDate===today)return;state.profile={...p,activeDays:p.lastActiveDate===prev?(p.activeDays||1)+1:1,lastActiveDate:today};try{localStorage.setItem(KEY,JSON.stringify(state))}catch{}}
async function render(){if(homeCarouselTimer)clearInterval(homeCarouselTimer);document.body.classList.remove('home-theme');const header=document.querySelector('header'),install=$('#install-app'),installHelp=$('#install-help');if(header&&install&&install.parentNode!==header)header.append(install);if(header&&installHelp&&installHelp.parentNode!==header)header.append(installHelp);const version=++renderVersion;document.querySelector('dialog')?.close();const path=location.hash.slice(1)||'inicio',parts=path.split('/');const avatar=document.querySelector('#header-profile-avatar');if(avatar){const selected=Math.max(1,Math.min(20,Number(String(state.profile?.avatar||'avatar-01').replace('avatar-',''))||1))-1;avatar.style.backgroundPosition=`${selected%5*25}% ${Math.floor(selected/5)*100/3}%`}document.querySelectorAll('[data-tab]').forEach(a=>a.classList.toggle('active',a.dataset.tab===parts[0]));if(policyDocs[path])return renderPolicy(path);if(parts[0]==='informacoes')return renderInfo();if(parts[0]==='inicio')return renderHome();if(parts[0]==='comunidade'){renderHome();requestAnimationFrame(()=>document.querySelector('#community-section')?.scrollIntoView({behavior:'smooth'}));return}if(parts[0]==='live-queue'){renderHome();requestAnimationFrame(()=>document.querySelector('#live-queue')?.scrollIntoView({behavior:'smooth'}));return}if(parts[0]==='comunidade-pagamento'&&parts[1]&&parts[2])return renderCommunityPayment(parts[1],parts[2],version);if(parts[0]==='perfil')return renderProfile();if(parts[0]==='controle'){app.innerHTML='<div class="empty"><h2>O controle tem uma área própria.</h2><p>O acesso é exclusivo da equipe autorizada.</p><a class="btn" href="#enviar">Voltar ao Hocco Message</a></div>';return}if(parts[0]==='acompanhar'&&parts.length===1)return renderLookup();if(['acompanhar','pagamento'].includes(parts[0])&&parts[1]){app.innerHTML='<div class="empty">Consultando seu pedido…</div>';try{const saved=state.orders.find(o=>o.code===parts[1]),key=parts[2]||saved?.trackingToken;if(!key)throw Error('Use o link privado completo recebido ao criar o pedido.');const d=await api('lookup',{code:parts[1],trackingToken:key});if(version!==renderVersion)return;const o=remember(d.order,key,d.history||[]);return parts[0]==='pagamento'?renderCheckout(o):renderOrder(o,d.history||[])}catch(e){if(version!==renderVersion)return;app.innerHTML=`<div class="empty"><h2>Não foi possível abrir o pedido.</h2><p>${esc(e.message)}</p><a href="#acompanhar" class="btn secondary">Voltar</a></div>`;return}}if(!catalog){app.innerHTML='<section class="narrow"><div class="empty"><h2>Preparando o Hocco Message…</h2><p>Carregando preços e disponibilidade.</p></div></section>';const loaded=await loadCatalog();if(version!==renderVersion)return;if(!loaded||!catalog){app.innerHTML='<section class="narrow"><div class="empty"><h2>O envio demorou para abrir.</h2><p>Não foi possível carregar preços e disponibilidade. Sua mensagem ainda não foi enviada nem cobrada.</p><button class="btn" id="retry-catalog" type="button">Tentar novamente</button></div></section>';$("#retry-catalog")?.addEventListener('click',()=>{catalog=null;render()});return}}renderCompose()}
function renderCompose(){const cfg=catalog?.settings,prices=cfg?.prices||[500,500,500,500,500],dateLabel=value=>value?new Date(value).toLocaleString('pt-BR',{dateStyle:'short',timeStyle:'short'}):'a definir';app.innerHTML=`<div class="compose-layout compose-cinematic"><section class="simulation-area"><div class="eyebrow">Hocco Message · sua mensagem dentro</div><h1>Sua mensagem<br><em>dentro do Reality da HOCCO.</em></h1><p class="lead">Seu recado aparece na imagem do vídeo oficial, na edição de um episódio da série documental da HOCCO — produzida em tempo real.</p><div class="video-preview" id="video-preview"><video autoplay muted playsinline loop preload="metadata" aria-label="Vídeo usado para visualizar sua mensagem"><source src="/assets/hocco-message-video.mp4" type="video/mp4"></video><div class="video-shade" aria-hidden="true"></div><div class="watching-label"><span>Você está assistindo</span><strong>| HOCCO.</strong></div><button class="preview-rotate" id="rotate-preview" type="button" aria-label="Girar tela e ampliar a prévia"><svg viewBox="0 0 24 24" aria-hidden="true"><path d="M4 8V4h4M20 16v4h-4M5.2 9a7 7 0 0 1 12-2L20 10M18.8 15a7 7 0 0 1-12 2L4 14"/></svg><span>Ver em tela cheia</span></button><button class="preview-exit" id="exit-preview" type="button">Sair da prévia</button><div class="rotation-hint" id="rotation-hint">Gire o aparelho para ver no formato horizontal do canal.</div><div class="message-slots" aria-label="Prévia de duas mensagens simultâneas">${[0,1].map(i=>`<div class="message-row ${i===(draft.slot%2===0?1:0)?'my-message':''}"><b aria-hidden="true">|</b><span>${i===(draft.slot%2===0?1:0)?esc(previewText()||'Sua mensagem'):'Uma nova história começa aqui.'}</span></div>`).join('')}</div></div><div class="preview-caption"><span>Prévia no formato do vídeo oficial</span><span>Duas mensagens por tela</span></div><div class="steps"><span><b>1</b> Escreva</span><span><b>2</b> Pague</span><span><b>3</b> Apareça</span></div></section><section class="form-side"><form id="message-form"><div class="form-top"><h2>Manda seu recado</h2><div class="price" id="current-price">${money(prices[draft.slot-1])}<small>por mensagem</small></div></div><div class="row"><span class="hint">${esc(cfg?.episode||'Carregamento indisponível')} · até ${dateLabel(cfg?.publication_deadline)}</span><span class="badge">${cfg?.display_duration_seconds||5}s · 2 posições por tela</span></div><div class="field"><label>Posição da sua mensagem</label><div class="slot-picker">${[1,2].map(i=>`<label class="slot-option"><input type="radio" name="slot" value="${i}" ${draft.slot===i?'checked':''} ${catalog?.availability[i-1]?.available===0?'disabled':''}><span><b>${i}</b><small>${money(prices[i-1])}</small></span></label>`).join('')}</div><small id="availability">${catalog?catalog.availability[draft.slot-1]?.available+' vagas nesta posição.':'Não foi possível consultar as vagas.'}</small></div><div class="field"><label for="name">Seu nome</label><input id="name" name="name" required maxlength="40" autocomplete="nickname" placeholder="Ex.: Alex, de Bauru" value="${esc(draft.name)}"></div><div class="field"><label for="social-platform">Rede social</label><select id="social-platform" name="socialPlatform" required><option value="instagram" ${draft.socialPlatform==='instagram'?'selected':''}>Instagram</option><option value="tiktok" ${draft.socialPlatform==='tiktok'?'selected':''}>TikTok</option></select></div><div class="field"><label for="social-handle">Seu @</label><input id="social-handle" name="socialHandle" required maxlength="31" pattern="@?[A-Za-z0-9._]{1,30}" placeholder="@seuperfil" value="${esc(draft.socialHandle)}"><small>Esse @ aparece junto da mensagem no vídeo.</small></div><div class="field"><label for="message">Sua mensagem</label><textarea id="message" name="message" required maxlength="180" placeholder="Escreva seu recado…">${esc(draft.text)}</textarea><div class="field-foot"><small>Duas mensagens aparecem por tela.</small><span class="counter" id="counter">${draft.text.length}/180</span></div></div><div class="field"><label for="phone">Seu WhatsApp (opcional)</label><input id="phone" name="phone" type="tel" maxlength="22" autocomplete="tel" placeholder="(DDD) 99999-9999" value="${esc(draft.phone)}"><small>Informe o número se escolher receber algum aviso. Ele não aparece no vídeo.</small></div><div class="acceptance-box"><label class="check"><input name="terms" type="checkbox" required><span>Tenho 18 anos ou mais e aceito os <a href="#termos">Termos de Uso</a>, as <a href="#regras">Regras</a> e os <a href="#cancelamentos">Cancelamentos</a>. Li a <a href="#privacidade">Política de Privacidade</a>.</span></label><label class="check"><input name="publication" type="checkbox" required><span>Autorizo a exibição pública do nome escolhido, da rede social, do @ e da mensagem no episódio contratado.</span></label>${catalog?.whatsappNoticeEnabled?'<label class="check"><input name="consent" type="checkbox"><span>Quero o aviso de veiculação no WhatsApp. <strong>Opcional.</strong></span></label>':''}${catalog?.remindersEnabled?'<label class="check"><input name="reminderConsent" type="checkbox"><span>Quero receber uma mensagem a cada 2 dias no WhatsApp para manter minha ofensiva na HOCCO e participar mais da história. Posso parar quando quiser.</span></label>':''}</div><button class="btn full" id="submit-message" style="margin-top:20px" ${!catalog||!catalog.paymentsEnabled?'disabled':''}>Continuar para pagamento →</button><div class="error" id="form-error" role="alert">${catalog&&!catalog.paymentsEnabled?'Envios temporariamente indisponíveis. Tente novamente em breve.':''}</div><p class="form-bottom">Sem criar conta. Você recebe um link privado de acompanhamento.</p></form></section></div>`;
 const preview=$('#video-preview'),rotate=$('#rotate-preview'),exit=$('#exit-preview'),syncPreview=()=>{const active=Boolean(document.fullscreenElement)||document.body.classList.contains('preview-fullscreen-fallback');rotate?.classList.toggle('is-hidden',active);exit?.classList.toggle('is-visible',active);$('#rotation-hint')?.classList.toggle('is-visible',active&&(!globalThis.screen?.orientation||!String(globalThis.screen.orientation.type||'').startsWith('landscape')))},leavePreview=async()=>{if(document.fullscreenElement){await document.exitFullscreen().catch(()=>{})}document.body.classList.remove('preview-fullscreen-fallback');globalThis.screen?.orientation?.unlock?.();syncPreview()};rotate?.addEventListener('click',async()=>{try{if(preview?.requestFullscreen){await preview.requestFullscreen({navigationUI:'hide'});try{await globalThis.screen?.orientation?.lock?.('landscape')}catch{}}else{document.body.classList.add('preview-fullscreen-fallback')}}catch{document.body.classList.add('preview-fullscreen-fallback')}syncPreview()});exit?.addEventListener('click',leavePreview);document.addEventListener?.('fullscreenchange',syncPreview);globalThis.screen?.orientation?.addEventListener?.('change',syncPreview);const form=$('#message-form'),update=()=>{const values=new FormData(form),slot=Number(values.get('slot')),ownIndex=slot%2===0?1:0;draft={name:$('#name').value,text:$('#message').value,phone:$('#phone').value,slot,socialPlatform:values.get('socialPlatform')||'instagram',socialHandle:$('#social-handle').value};document.querySelectorAll('.message-row').forEach((row,index)=>{const own=index===ownIndex;row.classList.toggle('my-message',own);row.querySelector('span').textContent=own?(previewText()||'Sua mensagem'):'Uma nova história começa aqui.'});$('#counter').textContent=draft.text.length+'/180';$('#current-price').innerHTML=`${money(prices[slot-1])}<small>por mensagem</small>`;$('#availability').textContent=catalog?catalog.availability[slot-1]?.available+' vagas nesta posição.':'Vagas indisponíveis.'};form.addEventListener('input',update);form.addEventListener('change',update);
form.onsubmit=async e=>{e.preventDefault();const f=new FormData(form);if(!draft.name.trim()||!draft.text.trim()||!draft.socialHandle.trim()){return $('#form-error').textContent='Preencha seu nome, seu @ e uma mensagem.'}const button=$('#submit-message');button.disabled=true;button.textContent='Registrando seu pedido…';requestToken||=token();try{const d=await api('create',{name:draft.name,message:draft.text,phone:draft.phone,slot:draft.slot,socialPlatform:draft.socialPlatform,socialHandle:draft.socialHandle,whatsappOptIn:f.get('consent')==='on',reminderOptIn:f.get('reminderConsent')==='on',terms:f.get('terms')==='on',adult:f.get('terms')==='on',publication:f.get('publication')==='on',legalVersion:LEGAL_VERSION,expectedPrice:catalog.settings.prices[draft.slot-1],settingsVersion:catalog.settings.version,trackingToken:requestToken});registerActiveDay();const o=remember(d.order,d.trackingToken,d.history||[]);requestToken=null;draft={name:'',text:'',phone:'',slot:1,socialPlatform:'instagram',socialHandle:''};location.hash=privateHash(o,'pagamento')}catch(error){if(error.message.includes('preços ou a oferta mudaram')){await loadCatalog();renderCompose();$('#form-error').textContent=error.message;return}$('#form-error').textContent=error.message;button.disabled=false;button.textContent='Continuar para pagamento →'}}}

const avatarCount=20;
function avatarArt(index){const safe=Math.max(0,Math.min(avatarCount-1,Number(index)||0)),col=safe%5,row=Math.floor(safe/5),x=col*25,y=(row*100/3).toFixed(3);return `<span class="avatar-portrait" aria-hidden="true" style="background-position:${x}% ${y}%"></span>`}
function renderLookup(){
 const orders=state.orders||[],community=state.communityOrders||[];
 const orderCards=orders.map(o=>`<a class="profile-history-card" href="#${privateHash(o)}"><span class="profile-history-bar" aria-hidden="true"></span><span class="profile-history-copy"><strong>| ${esc(o.message)}</strong><small>${esc(o.social_platform==='tiktok'?'TikTok':'Instagram')} · @${esc(o.social_handle||'')} · posição ${o.slot}</small></span><span class="profile-history-status">${badge(o)}<small>${esc(o.code)}</small></span><span class="profile-history-arrow" aria-hidden="true">›</span></a>`).join('');
 const communityCards=community.map(post=>{const isLive=post.destination==='live',status=communityStatus(post),paymentPath=`#comunidade-pagamento/${post.code}/${post.trackingToken}`;return `<a class="profile-history-card" href="${paymentPath}"><span class="profile-history-bar" aria-hidden="true"></span><span class="profile-history-copy"><strong>${esc(post.member_name||state.profile?.name||'Sua mensagem')}</strong><small>${isLive?'Próxima LIVE':'Comunidade'} · @${esc(post.member_username||state.profile?.username||'')}</small><span>${esc(post.message)}</span></span><span class="profile-history-status"><span class="badge ${post.review==='rejected'?'red':post.published_at?'success':'orange'}">${esc(status)}</span><small>${esc(post.code)}</small></span><span class="profile-history-arrow" aria-hidden="true">›</span></a>`}).join('');
 app.innerHTML=`<section class="profile-screen"><div class="profile-heading"><div class="eyebrow">HOCCO MESSAGE · MINHA ÁREA</div><h1>Acompanhar</h1><p>Veja o andamento e o histórico das suas mensagens.</p></div><div class="profile-history">${orderCards}${communityCards}${!orders.length&&!community.length?'<div class="profile-history-empty"><strong>Nenhuma mensagem neste aparelho ainda.</strong><span>Pedidos feitos neste navegador aparecem aqui. Em outro aparelho, abra o link privado recebido após o envio.</span></div>':''}</div><section class="paper tracking-lookup"><h2>Abrir um link privado</h2><p class="hint">Cole o link de acompanhamento que você recebeu. Só quem tem esse link consegue consultar o pedido.</p><form id="tracking-link-form"><div class="field"><label for="tracking-link">Link privado</label><input id="tracking-link" name="trackingLink" type="text" inputmode="url" autocomplete="url" placeholder="https://hocco-message.vercel.app/cliente/#acompanhar/…" required></div><div class="error" id="tracking-link-error" role="alert"></div><button class="btn purple full" type="submit">Abrir acompanhamento →</button></form></section><a class="btn secondary full" href="/#inicio">Voltar ao início</a></section>`;
 $('#tracking-link-form')?.addEventListener('submit',event=>{event.preventDefault();const error=$('#tracking-link-error'),raw=new FormData(event.currentTarget).get('trackingLink').trim();let fragment=raw;try{if(/^https?:\/\//i.test(raw))fragment=new URL(raw).hash.slice(1)}catch{}fragment=fragment.replace(/^#|^\/+/, '');const parts=fragment.split('/').filter(Boolean);let [kind,code,secret]=parts;if(/^HC-CM-[A-F0-9]{12}$/.test(code||'')){kind='comunidade-pagamento'}if(!['acompanhar','pagamento','comunidade-pagamento'].includes(kind)||!(/^(HM-26-[A-F0-9]{12}|HC-CM-[A-F0-9]{12})$/).test(code||'')||!(/^[a-f0-9]{64}$/).test(secret||'')){error.textContent='Esse link não parece ser um acompanhamento privado da HOCCO. Confira o link completo que recebeu.';return}location.hash=`#${kind}/${code}/${secret}`})
}
function renderProfile(){const p=state.profile||{},orders=state.orders||[],published=orders.filter(o=>o.delivery==='published').length,latest=orders.slice().sort((a,b)=>Date.parse(b.created_at||0)-Date.parse(a.created_at||0)),recent=latest.slice(0,2),streak=p.activeDays||0,selected=Math.max(0,Math.min(19,Number(String(p.avatar||'avatar-01').replace('avatar-',''))-1||0)),history=recent.length?recent.map(o=>`<a class="profile-history-card" href="#${privateHash(o)}"><span class="profile-history-bar" aria-hidden="true"></span><span class="profile-history-copy"><strong>| ${esc(o.message)}</strong><small>${esc(o.social_platform==='tiktok'?'TikTok':'Instagram')} · @${esc(o.social_handle||'')}</small></span><span class="profile-history-status">${badge(o)}<small>${o.created_at?new Date(o.created_at).toLocaleDateString('pt-BR',{day:'2-digit',month:'short',year:'numeric'}):'Data não disponível'}</small></span><span class="profile-history-arrow" aria-hidden="true">›</span></a>`).join(''):`<div class="profile-history-empty"><strong>Sua história começa aqui.</strong><span>Quando você enviar um recado, o status e o histórico aparecerão nesta área.</span><a class="btn secondary small" href="/#enviar">Enviar meu primeiro recado</a></div>`;app.innerHTML=`<section class="profile-screen"><div class="profile-heading"><div class="eyebrow">HOCCO MESSAGE</div><h1>Meu perfil</h1><p>Sua jornada no Reality da HOCCO.</p></div><form id="profile-form"><section class="profile-card" aria-label="Dados do perfil"><button class="profile-avatar-button" type="button" id="choose-profile-avatar" aria-label="Escolher figurante">${avatarArt(selected)}<span class="profile-edit-mark" aria-hidden="true"><svg viewBox="0 0 24 24"><path d="m12 5 2.2 4.5 5 .7-3.6 3.5.9 5-4.5-2.4-4.5 2.4.9-5-3.6-3.5 5-.7z"/></svg></span></button><div class="profile-identity"><label class="sr-only" for="profile-name">Nome do perfil</label><input id="profile-name" maxlength="40" value="${esc(p.name||'')}" placeholder="Seu nome" autocomplete="nickname"><label class="sr-only" for="profile-username">Seu nome de perfil com @</label><input id="profile-username" maxlength="25" value="${esc(p.username?'@'+p.username:'')}" placeholder="@seuperfil" autocomplete="username" inputmode="text" pattern="@?[A-Za-z0-9._]{3,24}" title="Use de 3 a 24 letras, números, pontos ou sublinhados."><span class="profile-active"><i aria-hidden="true"></i> Perfil ativo</span></div><button class="profile-save" type="submit">Salvar perfil</button><small class="profile-photo-hint">Este perfil, avatar e histórico ficam neste aparelho e neste navegador. Não há login nem sincronização entre aparelhos. Para consultar um pedido em outro dispositivo, use o link privado.</small></section></form><div class="profile-stats" aria-label="Resumo da sua atividade"><article class="profile-stat stat-purple"><svg viewBox="0 0 24 24" aria-hidden="true"><path d="M20 11.5a7.5 7.5 0 0 1-7.5 7.5H6l-3 2v-5.5a7.5 7.5 0 1 1 17.5-4Z"/></svg><span>Mensagens</span><strong>${String(orders.length).padStart(2,'0')}</strong></article><article class="profile-stat stat-orange"><svg viewBox="0 0 24 24" aria-hidden="true"><path d="M5 3.8v16.4L20 12 5 3.8Z"/></svg><span>Veiculadas</span><strong>${String(published).padStart(2,'0')}</strong></article><article class="profile-stat stat-lime"><svg viewBox="0 0 24 24" aria-hidden="true"><path d="M12 22s8-4.5 8-12V5l-8-3-8 3v5c0 7.5 8 12 8 12Z"/><path d="m9 12 2 2 4-4"/></svg><span>Ofensiva</span><strong>${String(streak).padStart(2,'0')} <small>${streak===1?'dia':'dias'}</small></strong></article></div><a class="profile-send-button" href="/#enviar"><svg viewBox="0 0 24 24"><path d="m22 2-7 20-4-9-9-4 20-7ZM22 2 11 13"/></svg>Enviar nova mensagem <span aria-hidden="true">›</span></a><div class="profile-history-heading"><h2>Meu histórico</h2><a href="#acompanhar">Ver tudo <span aria-hidden="true">›</span></a></div><div class="profile-history">${history}</div><a class="profile-info-link" href="/#informacoes">Sobre, termos e informações <span aria-hidden="true">›</span></a><section class="profile-reset"><button class="profile-reset-button" id="reset-profile" type="button">Resetar</button></section></section>`;$('#choose-profile-avatar').onclick=()=>{let pendingAvatar=selected+1;openDialog(`<div class="dialog-head"><div><div class="eyebrow">MEU PERFIL</div><h2>Figurantes</h2><p>Escolha um avatar para continuar.</p></div>${closeButton}</div><div class="avatar-picker" role="listbox" aria-label="Escolha um avatar">${Array.from({length:avatarCount},(_,i)=>`<button type="button" class="avatar-choice ${i===selected?'selected':''}" data-avatar="${i+1}" role="option" aria-selected="${i===selected}" aria-label="Figurante ${i+1}">${avatarArt(i)}</button>`).join('')}</div><button class="btn full avatar-confirm" id="confirm-avatar" type="button">Escolher</button>`);const dialog=document.querySelector('dialog');dialog?.querySelectorAll('[data-avatar]').forEach(button=>button.onclick=()=>{pendingAvatar=Number(button.dataset.avatar);dialog.querySelectorAll('[data-avatar]').forEach(option=>{const chosen=Number(option.dataset.avatar)===pendingAvatar;option.classList.toggle('selected',chosen);option.setAttribute('aria-selected',String(chosen))})});dialog?.querySelector('#confirm-avatar')?.addEventListener('click',()=>{state.profile={...p,avatar:`avatar-${String(pendingAvatar).padStart(2,'0')}`};if(!save()){state.profile={...p};toast('Não foi possível salvar este avatar neste aparelho.');return}const trigger=$('#choose-profile-avatar');trigger.innerHTML=avatarArt(pendingAvatar-1)+'<span class="profile-edit-mark" aria-hidden="true"><svg viewBox="0 0 24 24"><path d="m12 5 2.2 4.5 5 .7-3.6 3.5.9 5-4.5-2.4-4.5 2.4.9-5-3.6-3.5 5-.7z"/></svg></span>';dialog.close()});};$('#profile-form').onsubmit=e=>{e.preventDefault();const typed=$('#profile-name').value.trim().slice(0,40),raw=$('#profile-username').value.trim().replace(/^@+/,''),valid=/^[A-Za-z0-9._]{3,24}$/.test(raw);if(raw&&!valid){toast('Use de 3 a 24 letras, números, pontos ou sublinhados no @.');return}state.profile={...p,name:typed||'Minha área',username:raw,avatar:state.profile?.avatar||p.avatar||'avatar-01',activeDays:streak,lastActiveDate:p.lastActiveDate};if(!save())return;toast('Perfil salvo neste aparelho.')};$('#reset-profile').onclick=async()=>{if(!confirm('Isso apagará seus dados, pedidos e histórico deste perfil, além de zerar sua ofensiva. Mensagens já publicadas nos vídeos continuam lá. Esta ação não pode ser desfeita. Continuar?'))return;const button=$('#reset-profile');button.disabled=true;button.textContent='Apagando…';try{const owned=orders.filter(o=>/^HM-26-[A-F0-9]{12}$/.test(o.code||'')&&/^[a-f0-9]{64}$/.test(o.trackingToken||'')).map(o=>({code:o.code,trackingToken:o.trackingToken}));await api('customer.reset',{orders:owned});localStorage.removeItem(KEY);state={orders:[]};location.hash='#perfil';renderProfile();toast('Perfil e pedidos encontrados foram apagados.')}catch(error){toast(error.message||'Não foi possível resetar o app.');button.disabled=false;button.textContent='Resetar'}}}
