let homeSlideIndex=0;
function setHomeSlide(index){homeSlideIndex=(index+homeSlides.length)%homeSlides.length;const slide=homeSlides[homeSlideIndex],copy=$('.home-copy'),hero=$('.home-hero'),mascot=$('.home-mascot'),bubble=$('.home-bubble');if(!copy||!hero||!mascot||!bubble)return;copy.innerHTML=`<div class="home-brandline">${slide.eyebrow}</div><h1 class="home-title">${slide.title}</h1><p class="home-subtitle">${slide.subtitle}</p><a class="btn home-primary" href="${slide.href}" ${slide.external?'target="_blank" rel="noopener noreferrer"':''}><svg viewBox="0 0 24 24" aria-hidden="true"><path d="m22 2-7 20-4-9-9-4 20-7ZM22 2 11 13"/></svg>${slide.label}</a>`;mascot.style.backgroundPosition=`${(slide.avatar%5)*25}% ${Math.floor(slide.avatar/5)*100/3}%`;bubble.innerHTML=slide.bubble==='heart'?'<svg viewBox="0 0 24 24" aria-hidden="true"><path d="M20.8 4.6a5.5 5.5 0 0 0-7.8 0L12 5.7l-1.1-1.1a5.5 5.5 0 0 0-7.8 7.8l1.1 1.1L12 21l7.8-7.5 1.1-1.1a5.5 5.5 0 0 0-.1-7.8Z"/></svg>':`<span>${slide.bubble}</span>`;bubble.classList.toggle('home-bubble-label',slide.bubble!=='heart');hero.classList.remove('slide-changing');void hero.offsetWidth;hero.classList.add('slide-changing');hero.querySelectorAll('[data-hero-slide]').forEach((button,i)=>{button.classList.toggle('active',i===homeSlideIndex);button.setAttribute('aria-current',String(i===homeSlideIndex))})}
function renderHome(){
 if(communityFeedTimer)clearInterval(communityFeedTimer);if(communityCarouselTimer)clearInterval(communityCarouselTimer);if(homeCarouselTimer)clearInterval(homeCarouselTimer);
 document.body.classList.add('home-theme');
 app.innerHTML=`<div class="home-screen"><section class="home-hero" aria-label="Destaques da HOCCO"><div class="home-copy" aria-live="polite" aria-atomic="true"></div><div class="home-art" aria-hidden="true"><span class="home-stage-light"></span><span class="home-mascot"></span><span class="home-heart home-bubble"></span></div><div class="hero-pagination" role="group" aria-label="Destaques"><button type="button" data-hero-slide aria-label="Destaque 1"></button><button type="button" data-hero-slide aria-label="Destaque 2"></button><button type="button" data-hero-slide aria-label="Destaque 3"></button><button type="button" data-hero-slide aria-label="Destaque 4"></button><button type="button" data-hero-slide aria-label="Destaque 5"></button></div></section><section class="community-section" id="community-section" aria-labelledby="community-title"><div class="community-heading"><div><div class="home-section-kicker">HOCCO · JUNTO NA HISTÓRIA</div><h2 id="community-title">Comunidade</h2></div><a class="home-view-all" href="#comunidade">Ver todas <span aria-hidden="true">›</span></a></div><div class="community-carousel" id="community-carousel"><div class="community-track" id="community-track" aria-live="polite"><div class="community-empty">Carregando mensagens da Comunidade…</div></div></div><button class="btn community-send" id="community-send" type="button"><svg viewBox="0 0 24 24" aria-hidden="true"><path d="M21 3 10 14M21 3l-7 18-4-7-7-4 18-7Z"/></svg>Deixar uma mensagem</button></section><section class="live-community-card" id="live-queue" aria-labelledby="live-community-title"><div class="live-heading"><h2 id="live-community-title"><svg viewBox="0 0 24 24" aria-hidden="true"><path d="M2 9v6M6 5v14M10 8v8M14 3v18M18 7v10M22 10v4"/></svg>Fila da próxima LIVE</h2><span class="live-badge">LIVE</span><a href="#live-queue" class="home-view-all">Ver fila <span aria-hidden="true">›</span></a></div><div class="live-queue-list" id="live-queue-list"><div class="live-queue-empty">As mensagens destinadas à LIVE aparecerão aqui em ordem de entrada.</div></div><a class="tiktok-live-link" href="https://www.tiktok.com/@hoccobrasil" target="_blank" rel="noopener noreferrer"><svg viewBox="0 0 24 24" aria-hidden="true"><path d="M19.6 7.2c-1.5-.1-2.8-.9-3.6-2.1-.4-.6-.7-1.3-.8-2.1h-3.7v13.8c0 1.6-1.3 2.9-2.9 2.9s-2.9-1.3-2.9-2.9 1.3-2.9 2.9-2.9c.3 0 .6 0 .9.1v-3.8c-.3 0-.6-.1-.9-.1a6.7 6.7 0 1 0 6.7 6.7V9.6c1.3.9 2.9 1.4 4.6 1.4V7.2h-.3Z"/></svg><span>Assistir no TikTok</span><strong>@HOCCOBRASIL</strong><span class="tiktok-arrow" aria-hidden="true">›</span></a></section><div class="home-links"><a href="/ir-alem/#patrocinadores">Conheça quem financia</a><a href="/cliente/#acompanhar">Acompanhar mensagem</a></div></div>`;
 const header=document.querySelector('header'),install=$('#install-app'),installHelp=$('#install-help'),links=$('.home-links');if(links&&install)links.append(install);if(links&&installHelp)links.append(installHelp);
 setHomeSlide(0);const dots=[...document.querySelectorAll('[data-hero-slide]')];dots.forEach((button,index)=>button.addEventListener('click',()=>{setHomeSlide(index);restartHomeCarousel()}));
 const hero=$('.home-hero');let touchStartX=0;hero?.addEventListener('pointerdown',e=>{touchStartX=e.clientX},{passive:true});hero?.addEventListener('pointerup',e=>{const delta=e.clientX-touchStartX;if(Math.abs(delta)>45){setHomeSlide(homeSlideIndex+(delta<0?1:-1));restartHomeCarousel()}},{passive:true});
 restartHomeCarousel();
 $('#community-send').onclick=openCommunityComposer;loadCommunityFeed();communityFeedTimer=setInterval(loadCommunityFeed,30000);loadLiveQueue();liveQueueTimer=setInterval(loadLiveQueue,60000);
}
function restartHomeCarousel(){if(homeCarouselTimer)clearInterval(homeCarouselTimer);if(matchMedia('(prefers-reduced-motion: reduce)').matches)return;homeCarouselTimer=setInterval(()=>{const hero=$('.home-hero');if(!document.hidden&&!hero?.matches(':hover')&&!hero?.contains(document.activeElement))setHomeSlide(homeSlideIndex+1)},7000)}

function relativeCommunityTime(value){const minutes=Math.max(0,Math.floor((Date.now()-Date.parse(value||Date.now()))/60000));return minutes<1?'agora':minutes<60?`há ${minutes} min`:`há ${Math.floor(minutes/60)} h`}
function communityExpiry(value){const minutes=Math.max(0,Math.ceil((Date.parse(value||Date.now())-Date.now())/60000));return minutes<60?`Expira em ${minutes} min`:`Expira em ${Math.floor(minutes/60)} h`}
function communityVoterToken(){if(!/^[a-f0-9]{64}$/.test(state.communityVoterToken||'')){state.communityVoterToken=token();save()}return state.communityVoterToken}
async function loadCommunityFeed(){
 const track=$('#community-track');if(!track)return;
 try{
  const result=await api('community.feed'),messages=Array.isArray(result.messages)?result.messages:[];
  const signature=messages.map(post=>String(post.id)+':'+String(post.message)).join('|');
  if(signature&&signature===track.dataset.messageSignature){
   messages.forEach(post=>{const button=track.querySelector('[data-community-like="'+CSS.escape(String(post.id))+'"]'),count=button?.querySelector('.community-like-count');if(count)count.textContent=String(Math.max(0,Number(post.likes_count)||0))});
  }else{
   track.innerHTML=messages.length?messages.map(post=>{
    const key=String(post.id||''),liked=(state.communityLikes||[]).includes(key),count=Math.max(0,Number(post.likes_count)||0);
    return '<article class="community-card"><div class="community-card-head">'+avatarArt(Math.max(0,Math.min(19,Number(post.avatar_index||1)-1)))+'<div class="community-identity"><strong>'+esc(post.member_name)+'</strong><span>@'+esc(post.member_username)+'</span><small>'+relativeCommunityTime(post.published_at)+'</small></div></div><p>'+esc(post.message)+'</p><button class="community-like '+(liked?'is-liked':'')+'" type="button" data-community-like="'+esc(key)+'" aria-pressed="'+String(liked)+'" aria-label="'+(liked?'Remover gostei':'Gostei')+'. '+count+' curtidas"><svg viewBox="0 0 24 24" aria-hidden="true"><path d="M20.8 4.6a5.5 5.5 0 0 0-7.8 0L12 5.7l-1.1-1.1a5.5 5.5 0 0 0-7.8 7.8l1.1 1.1L12 21l7.8-7.5 1.1-1.1a5.5 5.5 0 0 0-.1-7.8Z"/></svg><span>Gostei</span><b class="community-like-count">'+count+'</b></button></article>'
   }).join(''):'<div class="community-empty">Ainda não há mensagens ativas. A primeira pode ser sua.</div>';
   track.dataset.messageSignature=signature;track.dataset.index='0';track.scrollTo({left:0,behavior:'instant'});
   track.querySelectorAll('[data-community-like]').forEach(button=>button.addEventListener('click',async()=>{
    const key=button.dataset.communityLike;if(!/^[0-9a-f-]{36}$/i.test(key)||button.disabled)return;
    state.communityLikes=Array.isArray(state.communityLikes)?state.communityLikes:[];
    const previousLiked=state.communityLikes.includes(key),targetLiked=!previousLiked,countNode=button.querySelector('.community-like-count'),previousCount=Math.max(0,Number(countNode?.textContent)||0);
    if(targetLiked)state.communityLikes.push(key);else state.communityLikes=state.communityLikes.filter(id=>id!==key);
    const paint=(liked,total)=>{button.classList.toggle('is-liked',liked);button.setAttribute('aria-pressed',String(liked));button.setAttribute('aria-label',(liked?'Remover gostei':'Gostei')+'. '+total+' curtidas');if(countNode)countNode.textContent=String(Math.max(0,total))};
    paint(targetLiked,Math.max(0,previousCount+(targetLiked?1:-1)));button.disabled=true;save();
    try{const response=await api('community.like',{messageId:key,voterToken:communityVoterToken(),liked:targetLiked});paint(Boolean(response.liked),Number(response.likesCount)||0)}
    catch(error){if(previousLiked&&!state.communityLikes.includes(key))state.communityLikes.push(key);if(!previousLiked)state.communityLikes=state.communityLikes.filter(id=>id!==key);paint(previousLiked,previousCount);save();toast(error.message||'Não foi possível registrar sua curtida.')}
    finally{button.disabled=false}
   }));
  }
  if(communityCarouselTimer)clearInterval(communityCarouselTimer);
  if(messages.length>3){communityCarouselTimer=setInterval(()=>{if(document.hidden||document.activeElement?.closest('.community-section'))return;moveCommunity(1)},7000)}
 }catch{track.innerHTML='<div class="community-empty">As mensagens da Comunidade não puderam ser carregadas agora.</div>'}
}
async function loadLiveQueue(){const list=$('#live-queue-list');if(!list)return;try{const result=await api('community.live_feed'),messages=Array.isArray(result.messages)?result.messages:[];list.innerHTML=messages.length?messages.map(post=>`<article class="live-queue-item">${avatarArt(Math.max(0,Math.min(19,Number(post.avatar_index||1)-1)))}<div><strong>@${esc(post.member_username)}</strong><p>${esc(post.message)}</p><small>Na fila · ${relativeCommunityTime(post.created_at)}</small></div></article>`).join(''):'<div class="live-queue-empty">As mensagens para a próxima LIVE aparecerão aqui após a confirmação do pagamento.</div>'}catch{list.innerHTML='<div class="live-queue-empty">A fila da próxima LIVE não pôde ser atualizada agora.</div>'}}
function moveCommunity(direction){const track=$('#community-track');if(!track)return;const cards=[...track.querySelectorAll('.community-card')];if(cards.length<2)return;let index=Number(track.dataset.index||0)+direction;if(index>=cards.length)index=0;if(index<0)index=cards.length-1;track.dataset.index=String(index);track.scrollTo({left:cards[index].offsetLeft,behavior:'smooth'})}
function openCommunityComposer(){
 const profile=state.profile||{},name=String(profile.name||'').trim(),username=String(profile.username||'').replace(/^@+/,''),avatar=Number(String(profile.avatar||'avatar-01').replace('avatar-',''));
 if(!name||! /^[A-Za-z0-9._]{3,24}$/.test(username)){toast('Complete seu nome e @ em Meu perfil para enviar.');location.hash='#perfil';return}
 openDialog(`<div class="dialog-head"><div><div class="eyebrow">HOCCO · COMUNIDADE E LIVE</div><h2>Para onde vai sua mensagem?</h2><p>Escolha onde quer participar. A mensagem passa pela checagem automática antes do pagamento.</p></div>${closeButton}</div><form id="community-form"><div class="community-profile-summary">${avatarArt(Math.max(0,Math.min(19,avatar-1)))}<div><strong>${esc(name)}</strong><span>@${esc(username)}</span></div></div><fieldset class="destination-picker"><legend>Escolha o destino</legend><label class="destination-option"><input type="radio" name="destination" value="community" checked><span><b>Comunidade</b><small>Visível no app por 4 horas</small><strong>${money(catalog?.settings?.community_price_cents??350)}</strong></span></label><label class="destination-option"><input type="radio" name="destination" value="live"><span><b>Próxima LIVE</b><small>Entra na fila de leitura do TikTok</small><strong>${money(catalog?.settings?.live_price_cents??550)}</span></label></fieldset><div class="field"><label for="community-message">Sua mensagem</label><textarea id="community-message" name="message" maxlength="180" required placeholder="Escreva sua mensagem…"></textarea><div class="field-foot"><small>Até 180 caracteres.</small><span id="community-counter">0/180</span></div></div><p class="hint" id="destination-hint">Após aprovação do conteúdo e confirmação do pagamento, a mensagem aparece na Comunidade por 4 horas.</p><div class="error" id="community-error" role="alert"></div><button class="btn full" type="submit">Continuar</button></form>`);
 const dialog=document.querySelector('dialog'),input=dialog?.querySelector('#community-message');
 input?.addEventListener('input',()=>{dialog.querySelector('#community-counter').textContent=input.value.length+'/180'});
 dialog?.querySelectorAll('input[name="destination"]').forEach(option=>option.addEventListener('change',()=>{dialog.querySelector('#destination-hint').textContent=option.value==='live'?'Após aprovação e confirmação do pagamento, ela entra na fila da próxima LIVE do TikTok.':'Após aprovação do conteúdo e confirmação do pagamento, a mensagem aparece na Comunidade por 4 horas.'}));
 dialog?.querySelector('#community-form')?.addEventListener('submit',async e=>{e.preventDefault();const button=dialog.querySelector('button[type="submit"]'),message=input.value.trim(),destination=new FormData(e.currentTarget).get('destination');if(!message)return;button.disabled=true;button.textContent='Preparando o pagamento…';try{const trackingToken=token(),result=await api('community.create',{name,username,avatar,message,destination,trackingToken});registerActiveDay();const entry={...result.post,trackingToken,pix:result.pix};state.communityOrders=[entry,...(state.communityOrders||[]).filter(x=>x.code!==entry.code)];save();dialog.close();location.hash=`#comunidade-pagamento/${entry.code}/${trackingToken}`}catch(error){dialog.querySelector('#community-error').textContent=error.message;button.disabled=false;button.textContent='Continuar'}})
}
function rememberCommunity(post,trackingToken,pix){const entry={...post,trackingToken,pix};state.communityOrders=[entry,...(state.communityOrders||[]).filter(x=>x.code!==entry.code)];save();return entry}
function communityStatus(post){if(post.review==='rejected')return post.payment==='refunded'?'Mensagem recusada · valor devolvido':'Mensagem recusada';if(post.destination==='live'&&post.live_status==='queued')return'Na fila da próxima LIVE';if(post.destination==='live'&&post.live_status==='read')return'Leitura registrada na LIVE';if(post.published_at&&Date.parse(post.expires_at)>Date.now())return'Visível na Comunidade';if(post.destination==='live'&&post.payment==='confirmed'&&post.review==='pending')return'Pagamento confirmado · revisão adicional';if(post.payment==='confirmed'&&post.review==='pending')return'Pagamento confirmado · revisão pendente';if(post.payment==='pending'&&post.payment_claimed)return'Pagamento informado · em conferência';if(post.review==='pending'&&post.payment==='pending')return'Revisão adicional antes do pagamento';if(post.review==='approved'&&post.payment==='pending')return'Aguardando confirmação do pagamento';return'Atualizando status'}
async function renderCommunityPayment(code,trackingToken,version){
 if(communityStatusTimer)clearInterval(communityStatusTimer);
 app.innerHTML='<section class="narrow"><div class="empty">Abrindo o acompanhamento da Comunidade…</div></section>';
 try{
  if(!/^HC-CM-[A-F0-9]{12}$/.test(code)||! /^[a-f0-9]{64}$/.test(trackingToken))throw Error('Link privado da mensagem inválido.');
  const result=await api('community.lookup',{code,trackingToken});
  if(version!==renderVersion)return;
  const post=rememberCommunity(result.post,trackingToken),rejected=post.review==='rejected',active=post.published_at&&Date.parse(post.expires_at)>Date.now();
  const isLive=post.destination==='live',destinationLabel=isLive?'Mensagem para a próxima LIVE':'Mensagem na Comunidade',durationLabel=isLive?'Leitura na próxima LIVE do TikTok':'Exibição por 4 horas na Comunidade';
  const paymentPanel=!rejected&&post.payment==='pending'&&post.review==='approved'
   ? `<section class="payment-method payment-card"><div class="payment-heading"><span class="payment-mark" aria-hidden="true">✓</span><div><span class="payment-kicker">Pagamento seguro</span><h2>Confirme seu pedido</h2></div><span class="badge">Mercado Pago</span></div><div class="payment-product"><div><strong>${destinationLabel}</strong><small>${durationLabel}</small></div><strong class="payment-amount">${money(post.price_cents)}</strong></div><button class="btn purple full payment-primary" id="mp-checkout-community">Pagar com Pix ou cartão <span aria-hidden="true">→</span></button><p class="hint">Você pode pagar por Pix ou cartão, mesmo sem conta no Mercado Pago. O QR Code Pix aparecerá no checkout seguro.</p><p class="payment-note">A confirmação chega automaticamente. ${isLive?'Depois, a mensagem entra na fila da próxima LIVE.':'Depois, a mensagem aprovada fica 4 horas na Comunidade.'}</p></section>`
   :!rejected&&post.payment==='pending'&&post.review==='pending'
    ?'<div class="note"><strong>Verificação adicional.</strong> Antes do pagamento, nossa equipe vai revisar esta mensagem. Acompanhe por este link; nenhuma cobrança foi iniciada.</div>'
   :!rejected&&post.payment==='confirmed'&&isLive
    ?`<div class="note"><strong>${post.live_status==='read'?'Leitura registrada na LIVE.':'Pagamento confirmado.'}</strong><p>${post.live_status==='queued'?'Sua mensagem está na fila da próxima LIVE do TikTok.':'O status da leitura foi atualizado pela equipe.'}</p></div>`
   :!rejected&&post.payment==='confirmed'
    ?'<div class="note"><strong>Pagamento confirmado automaticamente.</strong><p>Depois da checagem das regras, a mensagem aprovada aparece na Comunidade por 4 horas.</p></div>'
   :post.payment==='refunded'?'<div class="note">Pagamento devolvido.</div>':'';
  app.innerHTML=`<section class="narrow checkout community-checkout payment-screen"><div class="eyebrow">HOCCO · pagamento</div><h1 class="section-title">${post.destination==='live'?'Sua mensagem':'Seu pedido'}<br><em>${active?'na Comunidade':post.destination==='live'?'para a LIVE':'em andamento'}.</em></h1><p class="subheading">${esc(communityStatus(post))}</p><div class="paper"><div class="community-profile-summary">${avatarArt(Math.max(0,Math.min(19,Number(post.avatar_index||1)-1)))}<div><strong>${esc(post.member_name)}</strong><span>@${esc(post.member_username)}</span></div></div><p class="quote">${esc(post.message)}</p><div class="community-payment-total row"><span>${post.destination==='live'?'Próxima LIVE':'Comunidade'}</span><strong>${money(post.price_cents)}</strong></div>${post.published_at?'<p class="hint">'+(active?'Disponível até ':'Esta mensagem expirou na Comunidade · ')+new Date(post.expires_at).toLocaleString('pt-BR')+'</p>':''}${post.destination==='live'&&post.payment==='confirmed'?'<p class="hint">'+(post.live_status==='read'?'Leitura registrada.':'Sua mensagem aguarda a próxima LIVE do TikTok.')+'</p>':''}${rejected?'<div class="note"><strong>Mensagem recusada</strong><p>'+esc(post.reason||'A equipe decidiu não publicar esta mensagem.')+'</p>'+(post.payment==='confirmed'?'A equipe registrará a devolução.':post.payment==='refunded'?'Devolução registrada.':'')+'</div>':''}</div>${paymentPanel}<a class="btn secondary full" href="/#inicio">Voltar à página inicial</a><button class="btn ghost full" id="community-copy-link">Copiar link privado</button><p class="hint"><a href="#termos">Ver termos e política de reembolso</a></p></section>`;
  $('#community-copy-link')?.addEventListener('click',()=>copy(location.origin+location.pathname+'#comunidade-pagamento/'+code+'/'+trackingToken));
  $('#mp-checkout-community')?.addEventListener('click',async e=>{const button=e.currentTarget;button.disabled=true;button.textContent='Abrindo pagamento…';try{const checkout=await api('payment.checkout',{kind:'community',code,trackingToken});location.assign(checkout.checkoutUrl)}catch(error){button.disabled=false;button.textContent='Continuar para pagamento →';toast(error.message)}});
  communityStatusTimer=setInterval(async()=>{if(location.hash!=='#comunidade-pagamento/'+code+'/'+trackingToken)return;try{const latest=await api('community.lookup',{code,trackingToken});if(latest.post.updated_at!==post.updated_at||latest.post.review!==post.review||latest.post.payment!==post.payment||latest.post.live_status!==post.live_status)await renderCommunityPayment(code,trackingToken,version)}catch{}},25000);
 }catch(error){if(version!==renderVersion)return;app.innerHTML='<div class="empty"><h2>Não foi possível abrir a mensagem.</h2><p>'+esc(error.message)+'</p><a href="/#inicio" class="btn secondary">Voltar</a></div>'}
}
function renderCheckout(o){
 const pending=o.payment==='pending'&&o.review!=='rejected'&&o.delivery!=='published';
 const paymentPanel=pending
  ? '<section class="payment-method payment-card"><div class="payment-heading"><span class="payment-mark" aria-hidden="true">✓</span><div><span class="payment-kicker">Pagamento seguro</span><h2>Confirme seu pedido</h2></div><span class="badge">Mercado Pago</span></div><div class="payment-product"><div><strong>Mensagem no vídeo oficial</strong><small>Posição '+esc(String(o.slot))+' · '+esc(o.episode)+'</small></div><strong class="payment-amount">'+money(o.price_cents)+'</strong></div><button class="btn purple full payment-primary" id="mp-checkout-order">Pagar com Pix ou cartão <span aria-hidden="true">→</span></button><p class="hint">O QR Code Pix aparecerá no checkout seguro. Você também pode pagar com cartão, mesmo sem conta no Mercado Pago.</p><p class="payment-note">A confirmação chega automaticamente. Seu recado ainda passa pela curadoria antes de entrar no vídeo.</p></section>'
  :o.payment==='confirmed'
   ?'<div class="note"><strong>Pagamento confirmado automaticamente.</strong> Acompanhe aqui as atualizações da curadoria e da veiculação.</div>'
   :o.payment==='refunded'?'<div class="note">O pagamento foi devolvido.</div>':'';
 app.innerHTML=`<section class="narrow checkout"><div class="eyebrow">Hocco Message · pagamento</div><h1 class="section-title">Pagamento<br><em>do seu recado.</em></h1><p class="subheading">Pedido ${esc(o.code)} · posição ${o.slot}</p><div class="paper"><div class="row"><strong>${esc(o.name)}</strong><span class="badge">${esc(o.episode)}</span></div><p class="hint">Publicação até ${o.publication_deadline?new Date(o.publication_deadline).toLocaleString('pt-BR'):'a definir'} · ${o.display_duration_seconds||5}s na tela</p><p class="hint">${esc((o.social_platform==='tiktok'?'TikTok':'Instagram')+' @'+(o.social_handle||''))}</p><p class="quote">| @${esc(o.social_handle||'')} · ${esc(o.message)}</p><hr class="divider"><div class="row"><span>Valor total</span><strong>${money(o.price_cents)}</strong></div></div>${paymentPanel}<a class="btn secondary full" style="margin-top:10px" href="#${privateHash(o)}">Acompanhar meu recado →</a><p class="hint"><a href="#termos">Ver termos e política de reembolso</a></p><button class="btn ghost full" id="copy-tracking">Copiar link privado</button></section>`;
 $('#mp-checkout-order')?.addEventListener('click',async e=>{const button=e.currentTarget;button.disabled=true;button.textContent='Abrindo pagamento…';try{const checkout=await api('payment.checkout',{kind:'order',code:o.code,trackingToken:o.trackingToken});location.assign(checkout.checkoutUrl)}catch(error){toast(error.message);button.disabled=false;button.textContent='Continuar para pagamento →'}});
 $('#copy-tracking')?.addEventListener('click',()=>copy(location.origin+location.pathname+'#'+privateHash(o)))
}
function renderOrder(o,history=o.history||[]){const rejected=o.review==='rejected';if(trackingPoll)clearInterval(trackingPoll);const orderHash=location.hash;trackingPoll=setInterval(async()=>{if(location.hash!==orderHash)return;try{const fresh=await api('lookup',{code:o.code,trackingToken:o.trackingToken});const clean=value=>{const{trackingToken,history:ignored,...rest}=value;return rest};if(JSON.stringify(clean(fresh.order))!==JSON.stringify(clean(o))||JSON.stringify(fresh.history||[])!==JSON.stringify(history)){const next=remember(fresh.order,o.trackingToken,fresh.history||[]);renderOrder(next,fresh.history||[])}}catch{}},30000);app.innerHTML=`<section class="narrow tracking"><div class="eyebrow">Hocco Message · minha mensagem</div><h1 class="section-title">${o.delivery==='published'?'Seu recado<br><em>está no ar!</em>':'Seu recado está<br><em>a caminho.</em>'}</h1><p class="subheading">${esc(o.code)} · posição ${o.slot} · ${badge(o)}</p><div class="paper"><strong>${esc(o.name)}</strong><p class="hint">${esc((o.social_platform==='tiktok'?'TikTok':'Instagram')+' @'+(o.social_handle||''))}</p><p class="quote">| @${esc(o.social_handle||'')} · ${esc(o.message)}</p><div class="row"><span class="hint">${esc(o.episode)} · até ${o.publication_deadline?new Date(o.publication_deadline).toLocaleString('pt-BR'):'a definir'} · ${o.display_duration_seconds||5}s</span><strong>${money(o.price_cents)}</strong></div></div>${rejected?`<div class="note"><strong>Mensagem reprovada</strong><p>${esc(o.reason)}</p>${o.payment==='confirmed'?'Devolução pendente.':o.payment==='refunded'?'Devolução registrada.':'Não há pagamento confirmado.'}</div>`:`<ol class="timeline"><li class="done">Mensagem recebida</li><li class="${o.review==='approved'?'done':''}">Curadoria aprovada</li><li class="${o.payment==='confirmed'?'done':''}">Pagamento confirmado<small>${o.payment_claimed&&o.payment!=='confirmed'?'Você informou o pagamento. A equipe ainda precisa conferir.':'Confirmação independente da curadoria.'}</small></li><li class="${o.review==='approved'&&o.payment==='confirmed'?'done':''}">Fila de edição<small>Duas mensagens por tela; cada uma começa com |.</small></li><li class="${o.delivery==='published'?'done':''}">Mensagem veiculada</li></ol>`}${o.delivery==='published'?`<a class="btn purple full" href="${esc(o.video_url)}" target="_blank" rel="noopener noreferrer">▶ Ver minha mensagem no YouTube</a><p class="hint">${o.notification==='sent'?'Aviso enviado pelo WhatsApp.':'A equipe enviará o aviso pelo WhatsApp se você tiver autorizado esse contato.'}</p>`:!rejected?`<a class="btn secondary full" href="#${privateHash(o,'pagamento')}">Ver pagamento</a>`:''}${history.length?`<h2 class="history-title">Histórico deste comentário</h2><ol class="timeline status-history">${history.map(h=>`<li class="done">${esc(historyLabel(h.action))}${h.action==='reject'&&h.detail?.reason?`<small>Motivo: ${esc(h.detail.reason)}</small>`:''}<small>${new Date(h.created_at).toLocaleString('pt-BR')}</small></li>`).join('')}</ol>`:''}${o.reminder_active?'<button class="btn ghost full" id="stop-reminders">Parar lembretes a cada 2 dias</button>':''}<button class="btn ghost full" id="copy-tracking">Copiar link privado</button><a class="btn ghost" href="#acompanhar">← Meus pedidos</a></section>`;$('#copy-tracking').onclick=()=>copy(location.origin+location.pathname+'#'+privateHash(o));$('#stop-reminders')?.addEventListener('click',async()=>{if(!confirm('Parar os lembretes da ofensiva HOCCO?'))return;try{const result=await api('reminder_optout',{code:o.code,trackingToken:o.trackingToken});o.reminder_active=false;remember(o,o.trackingToken,result.history||history);renderOrder(o,result.history||history);toast('Lembretes cancelados.')}catch(e){toast(e.message)}})}
async function copy(text,notice='Link copiado. Guarde-o com você.'){try{await navigator.clipboard.writeText(text);toast(notice)}catch{openDialog(`<div class="dialog-top"><h2>Copie o conteúdo</h2>${closeButton}</div><textarea readonly aria-label="Conteúdo para copiar">${esc(text)}</textarea><p class="hint">Copie e guarde este link.</p>`)}}
function runScreenTransition(update,element=app,direction='forward'){
 if(matchMedia('(prefers-reduced-motion: reduce)').matches)return update();
 if(typeof document.startViewTransition==='function'){
  document.documentElement.dataset.hoccoDirection=direction;
  const transition=document.startViewTransition(()=>update());
  transition.finished.then(()=>delete document.documentElement.dataset.hoccoDirection,()=>delete document.documentElement.dataset.hoccoDirection);
  return transition;
 }
 const className=direction==='back'?'screen-swipe-back':'screen-swipe-forward';
 element.classList.remove('screen-swipe-back','screen-swipe-forward');
 element.classList.add(className);
 const result=update();
 setTimeout(()=>element.classList.remove(className),520);
 return result;
}
const routeRank=hash=>({inicio:0,enviar:1,pagamento:2,acompanhar:3,perfil:4,termos:5,privacidade:5,'previna-se':5,'informacoes':5}[(hash||'inicio').split('/')[0]]??2);
let previousRoute=location.hash.slice(1)||'inicio',exitBackUntil=0;
if(previousRoute==='inicio'&&!history.state?.hoccoExitGuard)history.pushState({...history.state,hoccoExitGuard:true},'',location.href);
window.addEventListener('popstate',event=>{const currentRoute=location.hash.slice(1)||'inicio';if(currentRoute!=='inicio'||event.state?.hoccoExitGuard)return;const now=Date.now();if(now<exitBackUntil){exitBackUntil=0;return}exitBackUntil=now+2000;toast('Pressione voltar novamente para sair.');history.pushState({...history.state,hoccoExitGuard:true},'',location.href)});
window.addEventListener('hashchange',()=>{if(trackingPoll)clearInterval(trackingPoll);const nextRoute=location.hash.slice(1)||'inicio',direction=routeRank(nextRoute)<routeRank(previousRoute)?'back':'forward';previousRoute=nextRoute;runScreenTransition(()=>render(),app,direction);window.scrollTo({top:0,behavior:'instant'})});render();
function renderInfo(){app.innerHTML=`<section class="legal-page information-page"><div class="eyebrow">HOCCO · informações</div><h1 class="section-title">Sobre e informações</h1><p class="subheading">Conheça o projeto, consulte os documentos e encontre os canais oficiais.</p><div class="info-link-list">${Object.entries(policyDocs).map(([id,doc])=>`<a class="info-link-row" href="#${id}"><span><strong>${esc(doc.title)}</strong><small>${esc(doc.intro)}</small></span><b aria-hidden="true">›</b></a>`).join('')}<a class="info-link-row" href="/ir-alem/"><span><strong>Conheça quem financia</strong><small>Veja as empresas que apoiam a HOCCO.</small></span><b aria-hidden="true">›</b></a><a class="info-link-row" href="https://www.youtube.com/@hoccpov" target="_blank" rel="noopener noreferrer"><span><strong>Canal oficial no YouTube</strong><small>Acompanhe os episódios da HOCCO.</small></span><b aria-hidden="true">↗</b></a><a class="info-link-row" href="https://www.tiktok.com/@hoccobrasil" target="_blank" rel="noopener noreferrer"><span><strong>HOCCO no TikTok</strong><small>Encontre as lives e os vídeos curtos.</small></span><b aria-hidden="true">↗</b></a></div><a href="#inicio" class="btn purple">Voltar ao início</a></section>`}
function renderPolicy(key){
 const doc=policyDocs[key];
 app.innerHTML=`<section class="legal-page"><div class="eyebrow">HOCCO · transparência</div><h1 class="section-title">${esc(doc.title)}</h1><p class="subheading">${esc(doc.intro)}</p><div class="legal-version">Versão ${LEGAL_VERSION} · ${LEGAL_DATE}</div><nav class="policy-tabs" aria-label="Documentos">${Object.entries(policyDocs).map(([id,d])=>`<a href="#${id}" ${id===key?'aria-current="page"':''}>${esc(d.title)}</a>`).join('')}</nav><div class="legal-summary"><h2>O essencial</h2><ul>${doc.summary.map(t=>`<li>${esc(t)}</li>`).join('')}</ul></div><article class="legal-text">${doc.sections.map(([title,body])=>`<section><h2>${esc(title)}</h2><p>${esc(body)}</p></section>`).join('')}</article><details class="rules"><summary>Referências oficiais consultadas</summary><ul>${legalSources.map(([title,url])=>`<li><a href="${url}" target="_blank" rel="noopener">${esc(title)} ↗</a></li>`).join('')}</ul></details><div class="legal-bottom"><a href="#enviar" class="btn purple">Voltar à minha mensagem →</a><button class="btn secondary" id="print-policy">Imprimir / salvar texto</button></div><p class="hint">O aceite dos termos e autorizações é registrado junto ao pedido no servidor.</p></section>`;
 $('#print-policy').onclick=()=>window.print();
}
